-- ─────────────────────────────────────────────────────────────
-- Leticia — log her first 3 weeks (days 1-4) with real weights.
-- Creates completed workouts so they show in her history & Progress.
-- Weights in kg; each weight applies to every set that day.
-- Sets = plan prescription; reps = plan lower bound.
-- ⚠️ EDIT Leticia's email before running.
-- Safe to re-run: it first deletes these 12 sessions, then re-creates them.
-- Sets use a running set_number so each exercise stays grouped and in order.
-- ─────────────────────────────────────────────────────────────
do $$
declare v_user uuid; v_plan uuid; v_wo uuid;
begin
  select id into v_user from users where lower(email) = lower('LETICIA_EMAIL_AQUI') limit 1;
  if v_user is null then raise exception 'No encontré a Leticia (revisa el correo).'; end if;
  select id into v_plan from plans where user_id = v_user order by is_active desc, created_at desc limit 1;

  delete from workouts where user_id = v_user and title in ('Semana 1 · Día 1', 'Semana 1 · Día 2', 'Semana 1 · Día 3', 'Semana 1 · Día 4', 'Semana 2 · Día 1', 'Semana 2 · Día 2', 'Semana 2 · Día 3', 'Semana 2 · Día 4', 'Semana 3 · Día 1', 'Semana 3 · Día 2', 'Semana 3 · Día 3', 'Semana 3 · Día 4');

  -- Semana 1 · Día 1

  -- Semana 1 · Día 2

  -- Semana 1 · Día 3

  -- Semana 1 · Día 4

  -- Semana 2 · Día 1

  -- Semana 2 · Día 2

  -- Semana 2 · Día 3

  -- Semana 2 · Día 4

  -- Semana 3 · Día 1

  -- Semana 3 · Día 2

  -- Semana 3 · Día 3

  -- Semana 3 · Día 4

  raise notice 'Listo: 12 entrenamientos (3 semanas x 4 días) registrados para Leticia.';
end $$;
